import{_ as o,C as e,c as a,o as n,a1 as d,G as s}from"./chunks/framework.6sy4tsQT.js";const p=JSON.parse('{"title":"交易员必备术语系统清单（程序员友好版）","description":null,"frontmatter":{"title":"交易员必备术语系统清单（程序员友好版）","description":null,"date":"2026-02-23T00:00:00.000Z","tags":["PSIF"],"outline":[2,3]},"headers":[],"relativePath":"trader/basic-trading-terms.md","filePath":"trader/basic-trading-terms.md"}'),l={name:"trader/basic-trading-terms.md"};function i(g,t,c,h,u,q){const r=e("Mermaid");return n(),a("div",null,[t[0]||(t[0]=d('<blockquote><p>专为程序员转行私募/证券交易员设计，按认知路径分层整理。</p></blockquote><h2 id="🔰-level-1-交易执行基础-先搞懂-怎么下单" tabindex="-1">🔰 Level 1：交易执行基础（先搞懂&quot;怎么下单&quot;） <a class="header-anchor" href="#🔰-level-1-交易执行基础-先搞懂-怎么下单" aria-label="Permalink to &quot;🔰 Level 1：交易执行基础（先搞懂&quot;怎么下单&quot;）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>核心解释</th><th>程序员类比</th></tr></thead><tbody><tr><td><strong>滑点</strong></td><td>Slippage</td><td>预期成交价与实际成交价的偏差，常因流动性不足或行情波动导致</td><td>类似&quot;异步请求的响应延迟&quot;，理论值≠实际值</td></tr><tr><td><strong>市价单</strong></td><td>Market Order</td><td>以当前市场最优价格立即成交</td><td><code>execute(price=best_available, urgency=high)</code></td></tr><tr><td><strong>限价单</strong></td><td>Limit Order</td><td>仅当价格≤指定价（买）或≥指定价（卖）时成交</td><td><code>if market_price &lt;= limit_price: fill_order()</code></td></tr><tr><td><strong>止损单</strong></td><td>Stop-Loss Order</td><td>价格触及预设阈值时自动转为市价单平仓</td><td><code>on_price_trigger(threshold): close_position()</code></td></tr><tr><td><strong>止盈单</strong></td><td>Take-Profit Order</td><td>达到目标盈利价位后自动平仓</td><td>同止损，方向相反</td></tr><tr><td><strong>冰山订单</strong></td><td>Iceberg Order</td><td>大额订单仅显示小部分，剩余隐藏分批执行</td><td>类似&quot;分页加载&quot;，避免暴露全部意图</td></tr><tr><td><strong>部分成交</strong></td><td>Partial Fill</td><td>订单仅部分被撮合，剩余继续挂单</td><td>类似&quot;批量接口返回部分成功&quot;</td></tr><tr><td><strong>买一/卖一</strong></td><td>Best Bid/Ask</td><td>订单簿中最高买价/最低卖价，即当前最优报价</td><td>优先队列的<code>peek()</code>操作</td></tr><tr><td><strong>盘口/订单簿</strong></td><td>Order Book (Level-1/2)</td><td>买卖挂单的价格-数量分布，Level-2含多档深度</td><td>类似&quot;双向优先队列+快照数据&quot;</td></tr><tr><td><strong>委比</strong></td><td>Order Imbalance</td><td><code>(委买量-委卖量)/(委买量+委卖量)</code>，衡量短期多空力量</td><td>请求队列的&quot;负载倾斜度&quot;</td></tr></tbody></table><blockquote><p>✅ 建议：先用模拟盘熟悉订单类型与盘口变化，理解&quot;价格发现&quot;的微观过程。</p></blockquote><hr><h2 id="📈-level-2-市场与行情理解-搞懂-数据从哪来" tabindex="-1">📈 Level 2：市场与行情理解（搞懂&quot;数据从哪来&quot;） <a class="header-anchor" href="#📈-level-2-市场与行情理解-搞懂-数据从哪来" aria-label="Permalink to &quot;📈 Level 2：市场与行情理解（搞懂&quot;数据从哪来&quot;）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>核心解释</th><th>关键要点</th></tr></thead><tbody><tr><td><strong>K线/OHLC</strong></td><td>Candlestick</td><td>开盘(Open)、最高(High)、最低(Low)、收盘(Close)的可视化</td><td>回测与策略开发的基础数据单元</td></tr><tr><td><strong>复权价格</strong></td><td>Adjusted Price</td><td>消除分红、送股、配股影响的历史价格</td><td><strong>回测必须用复权数据</strong>，否则信号失真</td></tr><tr><td><strong>前复权/后复权</strong></td><td>Forward/Backward Adjusted</td><td>以当前/历史某点为基准调整价格</td><td>前复权适合实盘参考，后复权适合长期回测</td></tr><tr><td><strong>跳空</strong></td><td>Gap</td><td>因隔夜消息等导致价格不连续，K线出现空缺</td><td>需特殊处理，避免策略误判</td></tr><tr><td><strong>流动性</strong></td><td>Liquidity</td><td>资产快速买卖且价格冲击小的能力</td><td>小盘股/冷门合约滑点大，慎重仓</td></tr><tr><td><strong>冲击成本</strong></td><td>Market Impact</td><td>大额订单自身推动价格不利变动造成的隐性成本</td><td>与滑点相关但成因不同，算法交易核心优化目标</td></tr><tr><td><strong>成交量/额</strong></td><td>Volume/Turnover</td><td>成交股数/成交金额，验证价格变动的有效性</td><td>&quot;量在价先&quot;是经典分析逻辑</td></tr><tr><td><strong>程序化交易</strong></td><td>Program Trading</td><td>通过预设算法自动执行交易，A股有专门监管要求[[49]]</td><td>私募合规重点，需备案策略逻辑</td></tr></tbody></table><blockquote><p>💡 程序员优势：您熟悉<code>pandas</code>处理时间序列，K线本质就是<code>DataFrame</code>中的<code>[ts, O, H, L, C, V]</code>六列。</p></blockquote><hr><h2 id="🧠-level-3-策略与量化核心-搞懂-怎么赚钱" tabindex="-1">🧠 Level 3：策略与量化核心（搞懂&quot;怎么赚钱&quot;） <a class="header-anchor" href="#🧠-level-3-策略与量化核心-搞懂-怎么赚钱" aria-label="Permalink to &quot;🧠 Level 3：策略与量化核心（搞懂&quot;怎么赚钱&quot;）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>核心解释</th><th>应用场景</th></tr></thead><tbody><tr><td><strong>因子</strong></td><td>Factor</td><td>能解释资产收益差异的变量（如动量、估值、波动率）</td><td>多因子选股、智能贝塔策略</td></tr><tr><td><strong>Alpha（α）</strong></td><td>Alpha</td><td>超越市场基准的超额收益，策略能力的体现</td><td>私募产品核心卖点</td></tr><tr><td><strong>Beta（β）</strong></td><td>Beta</td><td>资产对市场整体波动的敏感度，系统性风险敞口</td><td>对冲、资产配置基础</td></tr><tr><td><strong>夏普比率</strong></td><td>Sharpe Ratio</td><td><code>(年化收益-无风险利率)/年化波动率</code>，衡量风险调整后收益</td><td>策略对比、产品评级核心指标</td></tr><tr><td><strong>最大回撤</strong></td><td>Max Drawdown</td><td>历史任意时点买入后可能遭受的最大亏损幅度</td><td>风控硬约束，客户最敏感指标</td></tr><tr><td><strong>胜率/盈亏比</strong></td><td>Win Rate / Profit-Loss Ratio</td><td>盈利交易占比 / 平均盈利÷平均亏损</td><td>策略特征刻画，非越高越好</td></tr><tr><td><strong>过拟合</strong></td><td>Overfitting</td><td>策略在历史数据表现优异但实盘失效</td><td>回测需做样本外检验、参数敏感性分析</td></tr><tr><td><strong>未来函数</strong></td><td>Look-ahead Bias</td><td>回测中使用了当时不可得的数据（如用收盘价决定当日开盘买卖）</td><td><strong>代码审查重点</strong>，极易导致&quot;纸上富贵&quot;</td></tr><tr><td><strong>交易成本模型</strong></td><td>Transaction Cost Model</td><td>综合佣金、印花税、滑点、冲击成本的估算框架</td><td>策略实盘可行性评估必备</td></tr></tbody></table><blockquote><p>🎯 私募策略开发流程：<code>想法→因子挖掘→回测验证→实盘小资金试跑→风控嵌入→规模放大</code></p></blockquote><hr><h2 id="🛡️-level-4-风险与合规-搞懂-怎么不踩雷" tabindex="-1">🛡️ Level 4：风险与合规（搞懂&quot;怎么不踩雷&quot;） <a class="header-anchor" href="#🛡️-level-4-风险与合规-搞懂-怎么不踩雷" aria-label="Permalink to &quot;🛡️ Level 4：风险与合规（搞懂&quot;怎么不踩雷&quot;）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>核心解释</th><th>私募特殊性</th></tr></thead><tbody><tr><td><strong>合格投资者</strong></td><td>Qualified Investor</td><td>个人：金融资产≥300万或年收入≥50万；机构：净资产≥1000万[[8]]</td><td>私募募集前提，销售环节必核查</td></tr><tr><td><strong>开放日</strong></td><td>Subscription/Redemption Day</td><td>私募产品允许申购/赎回的固定日期（如每月10日）</td><td>流动性管理关键，非随时可进出</td></tr><tr><td><strong>预警线/止损线</strong></td><td>Warning/Stop-loss Line</td><td>净值下跌触发风控的阈值（如0.85预警、0.80强制止损）</td><td>产品合同强制约定，触及需减仓或清盘</td></tr><tr><td><strong>侧袋机制</strong></td><td>Side Pocket</td><td>将流动性差/估值难资产隔离存放，保护主袋投资者</td><td>应对债券违约、停牌股等极端情况</td></tr><tr><td><strong>穿透核查</strong></td><td>Look-through Verification</td><td>追溯最终投资者身份与资金来源，防止代持、嵌套</td><td>监管检查重点，IT系统需支持标签管理</td></tr><tr><td><strong>杠杆/融资</strong></td><td>Leverage / Margin</td><td>借入资金放大收益（同时放大风险）</td><td>私募证券基金杠杆比例有上限要求</td></tr><tr><td><strong>敞口</strong></td><td>Exposure</td><td>策略对某类风险（市场、行业、风格）的暴露程度</td><td>风控日报核心监控项</td></tr></tbody></table><blockquote><p>⚠️ 合规红线：程序化交易需向交易所报告策略类型、频率、风控措施[[50]]，&quot;技术中立&quot;不等于&quot;合规免责&quot;。</p></blockquote><hr><h2 id="⚙️-level-5-技术系统进阶-发挥程序员优势" tabindex="-1">⚙️ Level 5：技术系统进阶（发挥程序员优势） <a class="header-anchor" href="#⚙️-level-5-技术系统进阶-发挥程序员优势" aria-label="Permalink to &quot;⚙️ Level 5：技术系统进阶（发挥程序员优势）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>核心解释</th><th>技术关联</th></tr></thead><tbody><tr><td><strong>API接口</strong></td><td>Trading/Market Data API</td><td>连接券商/交易所获取行情、下单的程序接口</td><td>您熟悉的REST/WebSocket/FIX协议</td></tr><tr><td><strong>低延迟</strong></td><td>Low Latency</td><td>从信号生成到订单成交的全链路毫秒级优化</td><td>FPGA、内核旁路、共置部署等硬核技术</td></tr><tr><td><strong>回测框架</strong></td><td>Backtesting Engine</td><td>用历史数据模拟策略执行的系统</td><td>类似&quot;单元测试+压力测试+混沌工程&quot;</td></tr><tr><td><strong>事件驱动</strong></td><td>Event-Driven Architecture</td><td>按行情tick、订单成交等事件触发策略逻辑</td><td>比向量化回测更贴近实盘，但开发复杂度高</td></tr><tr><td><strong>订单路由</strong></td><td>Smart Order Routing (SOR)</td><td>智能选择最优交易所/流动性源执行订单</td><td>类似&quot;负载均衡+多活容灾&quot;策略</td></tr><tr><td><strong>实盘监控</strong></td><td>Live Monitoring &amp; Alert</td><td>实时跟踪策略P&amp;L、持仓、异常行为</td><td>类似APM+日志告警系统，需支持秒级响应</td></tr><tr><td><strong>风控引擎</strong></td><td>Risk Control Engine</td><td>事前校验、事中监控、事后分析的自动化风控</td><td>规则引擎+流计算，需与交易系统低耦合</td></tr></tbody></table><blockquote><p>🛠️ 推荐技术栈（A股方向）：</p><ul><li>数据：<code>akshare</code>/<code>tushare</code>（免费）、<code>Wind</code>/<code>iFinD</code>（机构付费）</li><li>回测：<code>backtrader</code>（灵活）、<code>vectorbt</code>（高速）、<code>Qlib</code>（微软开源）</li><li>实盘：<code>vn.py</code>（国产开源，支持多券商）、<code>RQSDK</code>（米筐）</li><li>监控：<code>Prometheus+Grafana</code> + 自定义告警规则</li></ul></blockquote><hr><h2 id="🗺️-学习路径建议-程序员专属" tabindex="-1">🗺️ 学习路径建议（程序员专属） <a class="header-anchor" href="#🗺️-学习路径建议-程序员专属" aria-label="Permalink to &quot;🗺️ 学习路径建议（程序员专属）&quot;">​</a></h2>',22)),s(r,{code:"graph%20LR%0AA%5B%E7%A8%8B%E5%BA%8F%E5%91%98%E8%83%8C%E6%99%AF%5D%20--%3E%20B%5BLevel1%3A%20%E8%AE%A2%E5%8D%95%E6%89%A7%E8%A1%8C%5D%0AB%20--%3E%20C%5BLevel2%3A%20%E8%A1%8C%E6%83%85%E6%95%B0%E6%8D%AE%5D%0AC%20--%3E%20D%5BLevel3%3A%20%E7%AD%96%E7%95%A5%E9%80%BB%E8%BE%91%5D%0AD%20--%3E%20E%5BLevel4%3A%20%E9%A3%8E%E6%8E%A7%E5%90%88%E8%A7%84%5D%0AE%20--%3E%20F%5BLevel5%3A%20%E7%B3%BB%E7%BB%9F%E4%BC%98%E5%8C%96%5D%0AF%20--%3E%20G%5B%E5%AE%9E%E7%9B%98%E5%B0%8F%E8%B5%84%E9%87%91%E9%AA%8C%E8%AF%81%5D%0A"}),t[1]||(t[1]=d('<h3 id="📌-三阶段行动清单" tabindex="-1">📌 三阶段行动清单： <a class="header-anchor" href="#📌-三阶段行动清单" aria-label="Permalink to &quot;📌 三阶段行动清单：&quot;">​</a></h3><ol><li><strong>第1-2周</strong>：用<code>vn.py</code>模拟盘跑通&quot;限价单+止损单&quot;，观察滑点与盘口变化</li><li><strong>第3-4周</strong>：用<code>akshare</code>下载沪深300成分股数据，实现一个简单动量策略回测</li><li><strong>第5-6周</strong>：阅读《私募投资基金监督管理暂行办法》，理解合格投资者、预警线等合规要求</li></ol><h3 id="📚-推荐延伸资料" tabindex="-1">📚 推荐延伸资料： <a class="header-anchor" href="#📚-推荐延伸资料" aria-label="Permalink to &quot;📚 推荐延伸资料：&quot;">​</a></h3><ul><li>书籍：《主动投资组合管理》（Grinold &amp; Kahn）、《量化交易：如何建立自己的算法交易事业》</li><li>法规：中国基金业协会《私募投资基金备案须知》《程序化交易管理暂行规定》</li><li>社区：JoinQuant聚宽、RiceQuant米筐的策略分享区（注意脱敏）</li></ul><hr><blockquote><p>💬 <strong>最后提醒</strong>：交易员的核心能力 = <strong>技术实现力 × 市场理解力 × 风控敬畏心</strong>。程序员转型的最大优势是&quot;能把想法快速变成可验证的代码&quot;，但需警惕&quot;过度优化历史数据&quot;的陷阱。建议从小资金、低频策略起步，先跑通&quot;想法→代码→回测→实盘&quot;的完整闭环。</p></blockquote><p>如需某个术语的深度解析、代码示例或学习资源推荐，欢迎随时告诉我！🚀</p>',7))])}const E=o(l,[["render",i]]);export{p as __pageData,E as default};
